import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";

const AIAssistant: React.FC = () => {
  const [userInput, setUserInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<{ estimation: string; advice: string } | null>(null);

  const generateEstimate = async () => {
    if (!userInput.trim()) return;
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analysiere folgende Reinigungsanfrage für eine neue Firma namens SparkleFlow. Schätze die ungefähre Dauer in Stunden und gib einen kurzen, professionellen Ratschlag. Der Benutzer sagt: "${userInput}". 
        Antworte ausschließlich im JSON-Format mit den Feldern 'estimation' (z.B. "2-3 Stunden") und 'advice' (kurzer Tipp). Sprache: Deutsch.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              estimation: { type: Type.STRING },
              advice: { type: Type.STRING }
            },
            required: ["estimation", "advice"]
          }
        }
      });

      const data = JSON.parse(response.text);
      setResult(data);
    } catch (error) {
      console.error("AI Error:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="ai-assistant" className="py-24 bg-blue-900 text-white overflow-hidden relative">
      <div className="max-w-4xl mx-auto px-4 relative z-10">
        <div className="text-center mb-12">
          <h2 className="text-4xl font-bold mb-4">Intelligenter Preis-Check</h2>
          <p className="text-blue-200 text-lg">
            Beschreiben Sie kurz, was gereinigt werden soll (z.B. "3-Zimmer Wohnung, 80qm, Fenster putzen") und unsere KI gibt Ihnen eine erste Einschätzung.
          </p>
        </div>

        <div className="bg-white rounded-2xl p-6 md:p-8 shadow-2xl text-slate-900">
          <textarea
            className="w-full h-32 p-4 border border-slate-200 rounded-xl mb-4 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            placeholder="Beschreiben Sie Ihr Projekt..."
            value={userInput}
            onChange={(e) => setUserInput(e.target.value)}
          ></textarea>

          <button
            onClick={generateEstimate}
            disabled={loading || !userInput}
            className={`w-full py-4 rounded-xl font-bold text-white transition-all ${loading ? 'bg-slate-400' : 'bg-blue-600 hover:bg-blue-700'}`}
          >
            {loading ? 'Berechne Einschätzung...' : 'Einschätzung jetzt anfordern'}
          </button>

          {result && (
            <div className="mt-8 p-6 bg-blue-50 border border-blue-100 rounded-xl animate-fade-in">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center text-white">✨</div>
                <div>
                  <h4 className="font-bold text-blue-900">Ungefähre Dauer: {result.estimation}</h4>
                  <p className="text-sm text-blue-700">Diese Schätzung ist unverbindlich und hilft bei der Planung.</p>
                </div>
              </div>
              <p className="text-slate-700 italic">" {result.advice} "</p>
            </div>
          )}
        </div>
      </div>
      <div className="absolute top-0 right-0 -translate-y-1/2 translate-x-1/3 w-[500px] h-[500px] bg-blue-500 rounded-full opacity-20 blur-[100px]"></div>
    </section>
  );
};

export default AIAssistant;

